              {
                $con->commit();
                return;
              }
            }

            if ($ret) {
                $deleteQuery->delete($con);
                $this->postDelete($con);
                // symfony_behaviors behavior
                foreach (sfMixer::getCallables('BaseProcedimiento:delete:post') as $callable)
                {
                  call_user_func($callable, $this, $con);
                }

                $con->commit();
