                $this->setDependencia($this->aDependencia);
            }

            if ($this->isNew() || $this->isModified()) {
                // persist changes
                if ($this->isNew()) {
                    $this->doInsert($con);
                } else {
                    $this->doUpdate($con);
                }
                $affectedRows += 1;
                $this->resetModified();
            }

            if ($this->procedimientoAprobsScheduledForDeletion !== null) {
                if (!$this->procedimientoAprobsScheduledForDeletion->isEmpty()) {
                    ProcedimientoAprobQuery::create()
