    {
        $this->modifiedColumns[] = ProcedimientoPeer::PROCEDIMIENTO_ID;
        $criteria = $this->buildCriteria();
        if ($criteria->keyContainsValue(ProcedimientoPeer::PROCEDIMIENTO_ID) ) {
            throw new PropelException('Cannot insert a value for auto-increment primary key (' . ProcedimientoPeer::PROCEDIMIENTO_ID . ')');
        }
        // remove pkey col since this table uses auto-increment and passing a null value for it is not valid
        $criteria->remove(ProcedimientoPeer::PROCEDIMIENTO_ID);
        $pk = BasePeer::doInsert($criteria, $con);
        $this->setProcedimientoId($pk);  //[IMV] update autoincrement primary key
        $this->setNew(false);
